{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    total_min = sum(alloc)
    if budget < total_min:
        raise ValueError('Budget below minimum quota sum')
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget > total_cap:
        raise ValueError('Budget exceeds total capacity')
    remaining = budget - total_min
    while remaining > 0:
        best_idx = -1
        best_imp = None
        best_denom = None
        for i in range(n):
            if alloc[i] < segments[i]['capacity']:
                imp = segments[i]['importance']
                denom = alloc[i] + 1
                if best_idx == -1:
                    best_idx = i
                    best_imp = imp
                    best_denom = denom
                else:
                    # compare imp/denom vs best_imp/best_denom
                    # imp/denom > best_imp/best_denom iff imp*best_denom > best_imp*denom
                    if imp * best_denom > best_imp * denom:
                        best_idx = i
                        best_imp = imp
                        best_denom = denom
                    # tie: keep original order (i is later, so no change)
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': sum(alloc)
    }"}
